import mongoose from 'mongoose';
import dotenv from 'dotenv';
import path from 'path';

dotenv.config({ path: path.resolve(__dirname, '../../../.env') });

async function cleanDuplicates() {
  const uri = process.env.MONGODB_URI;
  if (!uri) throw new Error('MONGODB_URI missing');

  await mongoose.connect(uri);
  console.log('Connected to MongoDB Atlas.');

  const productsColl = mongoose.connection.collection('products');
  const txColl = mongoose.connection.collection('transactions');

  // 1. Delete test transactions generated by testEndpoints.ts
  const delTxResult = await txColl.deleteMany({ uuid: { $regex: '^test-uuid-' } });
  console.log(`Deleted ${delTxResult.deletedCount} automated test transaction(s).`);

  // 2. Identify duplicate Coke Original products to remove
  // We keep 6af028e396dbb9f454a718c7 as the canonical one
  const canonicalId = new mongoose.Types.ObjectId('6af028e396dbb9f454a718c7');
  
  const duplicates = await productsColl.find({
    product_name: 'Coke Original',
    _id: { $ne: canonicalId },
  }).toArray();

  console.log(`Found ${duplicates.length} duplicate Coke Original product(s) to remove:`);
  for (const d of duplicates) {
    console.log(` - Removing duplicate ID: ${d._id}`);
    await productsColl.deleteOne({ _id: d._id });
  }

  // 3. Print remaining clean products catalog
  const remaining = await productsColl.find({}).sort({ brand_name: 1, product_name: 1 }).toArray();
  console.log(`\nRemaining Clean Catalog (${remaining.length} products):`);
  for (const p of remaining) {
    console.log(` ✓ [${p._id}] ${p.brand_name} - ${p.product_name} (${p.bottle_size}) | Stock: ${p.total_stock_bottles} bottles`);
  }

  await mongoose.disconnect();
  console.log('\nDone.');
}

cleanDuplicates().catch(console.error);
